#define FABLE_RETAIL_CCHARSTRING_WHITESPACE
#define FABLE_RETAIL_CWIDESTRING
#define FABLE_RETAIL_CAFILE
#define FABLE_RETAIL_CAFILE_SPLITPATH_WIDE
#define FABLE_RETAIL_CMEMORYFILE
